// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
import { Triangle } from "@remotion/shapes";

{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}

// --- SVG PATHS (Stylized Low-Poly Approximation of Germany) ---
const GERMANY_PATH = "M 180 50 L 260 20 L 350 30 L 380 70 L 450 60 L 480 90 L 430 150 L 500 180 L 540 250 L 580 350 L 520 400 L 550 500 L 560 650 L 500 700 L 400 750 L 300 780 L 200 770 L 150 720 L 100 700 L 80 600 L 50 550 L 40 450 L 80 400 L 60 300 L 100 250 L 80 150 L 130 100 L 180 50 Z";
const BW_PATH = "M 160 560 L 260 550 L 300 680 L 280 770 L 200 770 L 150 720 L 100 700 L 80 600 L 160 560 Z";
const BY_PATH = "M 280 540 L 450 500 L 540 520 L 560 650 L 500 700 L 400 750 L 300 780 L 280 770 L 300 680 L 280 540 Z";



export type GermanyMapHighlightProps = Record<string, any>;

const GermanyMapHighlight: React.FC<GermanyMapHighlightProps> = ({
  backgroundColor = "#f0f4f8",
  transparentBackground = false,
  durationInSeconds = 8,
  mapBaseColor = "#cbd5e1",
  bwHighlightColor = "#f59e0b",
  byHighlightColor = "#3b82f6",
  mapStrokeColor = "#ffffff",
  arrowColor = "#ef4444",
  textColor = "#1e293b",
  strokeWidth = 3,
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Animation Timings
  const mapEntrance = spring({
    frame,
    fps,
    config: { damping: 20 },
    delay: 0,
  });

  const highlightsEntrance = spring({
    frame: frame - 20,
    fps,
    config: { damping: 20 },
  });

  const arrowEntrance = spring({
    frame: frame - 45,
    fps,
    config: { stiffness: 80, damping: 15 },
  });

  // Scale factor to fit map in 1920x1080
  const scale = (height * 0.85) / 800;
  const translateX = width / 2 - (300 * scale);
  const translateY = height / 2 - (400 * scale);

  const bwCenter = { x: 190 * scale + translateX, y: 660 * scale + translateY };
  const byCenter = { x: 420 * scale + translateX, y: 640 * scale + translateY };

  // Arrow Parameters
  // Arrow starts are calculated relative to centers to place labels nicely
  const arrowDistParam = 150; 
  const bwArrowStart = { x: bwCenter.x - arrowDistParam, y: bwCenter.y - 50 };
  const byArrowStart = { x: byCenter.x + arrowDistParam, y: byCenter.y - 80 };

  const arrowStrokeWidth = 8;
  const arrowHeadSize = 30;

  // Geometry Helper
  const calculateArrowGeometry = (start: {x: number, y: number}, end: {x: number, y: number}) => {
    const dx = end.x - start.x;
    const dy = end.y - start.y;
    const angle = Math.atan2(dy, dx) * (180 / Math.PI);
    const length = Math.sqrt(dx * dx + dy * dy);
    return { angle, length };
  };

  const bwGeo = calculateArrowGeometry(bwArrowStart, bwCenter);
  const byGeo = calculateArrowGeometry(byArrowStart, byCenter);

  // Interpolated Arrow Values
  const bwArrowProgress = interpolate(arrowEntrance, [0, 1], [0, 1], { extrapolateRight: "clamp" });
  const byArrowProgress = interpolate(arrowEntrance, [0, 1], [0, 1], { extrapolateRight: "clamp" });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Inter" }}>
      
      {/* Container for the Map */}
      <div
        style={{
          position: "absolute",
          left: translateX,
          top: translateY,
          transform: `scale(${mapEntrance})`,
          transformOrigin: "center center",
        }}
      >
        <svg
          width={600 * scale}
          height={800 * scale}
          viewBox="0 0 600 800"
          style={{ overflow: "visible" }}
        >
          {/* Base Germany Map */}
          <path
            d={GERMANY_PATH}
            fill={mapBaseColor}
            stroke={mapStrokeColor}
            strokeWidth={strokeWidth}
            style={{
              filter: "drop-shadow(0px 10px 20px rgba(0,0,0,0.15))"
            }}
          />

          {/* Baden-Württemberg Highlight */}
          <path
            d={BW_PATH}
            fill={bwHighlightColor}
            stroke={mapStrokeColor}
            strokeWidth={strokeWidth}
            style={{
              opacity: highlightsEntrance,
              transform: `scale(${interpolate(highlightsEntrance, [0, 1], [0.9, 1])})`,
              transformOrigin: "200px 680px", 
            }}
          />

          {/* Bavaria Highlight */}
          <path
            d={BY_PATH}
            fill={byHighlightColor}
            stroke={mapStrokeColor}
            strokeWidth={strokeWidth}
            style={{
              opacity: highlightsEntrance,
              transform: `scale(${interpolate(highlightsEntrance, [0, 1], [0.9, 1])})`,
              transformOrigin: "420px 650px", 
            }}
          />
        </svg>
      </div>

      {/* ARROWS LAYER */}
      
      {/* Arrow for Baden-Württemberg */}
      <div style={{
          position: "absolute",
          left: bwArrowStart.x,
          top: bwArrowStart.y,
          opacity: bwArrowProgress,
          // Slide in from left
          transform: `translate(${interpolate(bwArrowProgress, [0, 1], [-50, 0])}px, 0px)`,
      }}>
        {/* Label (Static relative to start) */}
        <div style={{ 
            position: "absolute", 
            bottom: "100%", 
            left: 0, 
            whiteSpace: "nowrap",
            fontSize: 40,
            fontWeight: 700,
            color: textColor,
            marginBottom: 10,
        }}>
          Baden-Württemberg
        </div>
        
        {/* Rotated Arrow Container */}
        <div style={{
          position: "absolute",
          left: 0,
          top: 0,
          transform: `rotate(${bwGeo.angle}deg)`,
          transformOrigin: "left center", // Rotate from start point
        }}>
           {/* Shaft */}
           <div style={{
              width: interpolate(bwArrowProgress, [0, 1], [0, bwGeo.length]),
              height: arrowStrokeWidth,
              backgroundColor: arrowColor,
              borderRadius: arrowStrokeWidth,
              transformOrigin: "left center",
           }} />
           
           {/* Head */}
           <div style={{
               position: "absolute",
               left: interpolate(bwArrowProgress, [0, 1], [0, bwGeo.length]),
               top: arrowStrokeWidth / 2, // Centered vertically on shaft
               transform: `translate(-5px, -50%)`, // -5px to slightly overlap shaft, -50% to center vertically
           }}>
              <Triangle length={arrowHeadSize} fill={arrowColor} direction="right" />
           </div>
        </div>
      </div>


      {/* Arrow for Bavaria */}
      <div style={{
          position: "absolute",
          left: byArrowStart.x,
          top: byArrowStart.y,
          opacity: byArrowProgress,
          // Slide in from right
          transform: `translate(${interpolate(byArrowProgress, [0, 1], [50, 0])}px, 0px)`,
      }}>
         {/* Label (Aligned right) */}
         <div style={{ 
            position: "absolute", 
            bottom: "100%", 
            right: 0, // Align right to the start point
            whiteSpace: "nowrap",
            fontSize: 40,
            fontWeight: 700,
            color: textColor,
            marginBottom: 10,
        }}>
          Bavaria
        </div>

        {/* Rotated Arrow Container */}
        <div style={{
          position: "absolute",
          left: 0,
          top: 0,
          transform: `rotate(${byGeo.angle}deg)`,
          transformOrigin: "left center", // Rotate from start point
        }}>
           {/* Shaft */}
           <div style={{
              width: interpolate(byArrowProgress, [0, 1], [0, byGeo.length]),
              height: arrowStrokeWidth,
              backgroundColor: arrowColor,
              borderRadius: arrowStrokeWidth,
              transformOrigin: "left center",
           }} />
           
           {/* Head */}
           <div style={{
               position: "absolute",
               left: interpolate(byArrowProgress, [0, 1], [0, byGeo.length]),
               top: arrowStrokeWidth / 2,
               transform: `translate(-5px, -50%)`,
           }}>
              <Triangle length={arrowHeadSize} fill={arrowColor} direction="right" />
           </div>
        </div>
      </div>

    </AbsoluteFill>
  );
};

export default GermanyMapHighlight;